def normalize(comp):
    """A shape's cells shifted so its top-left corner of the bounding box is (0, 0)."""
    mr = min(r for r, c in comp); mc = min(c for r, c in comp)
    return sorted((r - mr, c - mc) for r, c in comp)

def shape_size(comp):
    """A shape's cell count."""
    return len(comp)

def shape_dims(comp):
    """A shape's (height, width)."""
    return (max(r for r, c in comp) - min(r for r, c in comp) + 1,
            max(c for r, c in comp) - min(c for r, c in comp) + 1)

def paste(grid, comp, color, dr, dc):
    """Copy a shape's cells, offset by (dr, dc), onto the grid in the given color."""
    for r, c in comp:
        grid[r + dr][c + dc] = color
    return grid

def pair_stack(grid):
    """Two shapes per color: the smaller (tie: originally lower) sits one clear row above the larger, both bottom-anchored at the last row, each color's pair left-aligned in its own column group, the group of the color holding the leftmost cell at column 0 and the other one column after the first group's widest shape."""
    H, W = len(grid), len(grid[0])
    bycol = {}
    for col, comp in shapes(grid):
        bycol.setdefault(col, []).append(comp)
    left = min(bycol, key=lambda c: min(c2 for comp in bycol[c] for r, c2 in comp))
    right = [c for c in bycol if c != left][0]
    out = [[0] * W for _ in range(H)]
    start = {left: 0}
    start[right] = max(shape_dims(comp)[1] for comp in bycol[left]) + 1
    for col in (left, right):
        a, b = bycol[col]
        small, big = sorted(bycol[col], key=lambda s: (shape_size(s), -min(r for r, c in s)))
        for comp, endrow in ((small, H - 1 - shape_dims(big)[0] - 1), (big, H - 1)):
            mc = min(c for r, c in comp); mr = max(r for r, c in comp)
            paste(out, comp, col, endrow - mr, start[col] - mc)
